{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What areas around Birmingham do you serve?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We primarily serve the Over the Mountain communities including Vestavia Hills, Mountain Brook, Homewood, and Hoover along with the greater Birmingham metro area. Our office is at 219 Oxmoor Circle, Suite 129, Homewood, AL 35209. If you are not sure whether your neighborhood is in our service area, call 205-273-2773 and we will tell you straight."
      }
    },
    {
      "@type": "Question",
      "name": "What is a design-build remodeler, and why does it matter to me?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A design-build firm handles both the design and the construction of your project instead of handing you off between an outside designer and a separate builder. One team, one plan, one contract. In practice that means better coordination, fewer things lost in translation, and designs that are actually buildable."
      }
    },
    {
      "@type": "Question",
      "name": "Is ELM Construction licensed and insured?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We are licensed by the State of Alabama as a Residential Home Builder and Remodeler under license number 21942, and we are fully insured with both General Liability and Workers Compensation coverage. We are also an Alabama Accredited Lead-Based Paint Renovator, which matters on any home built before 1978."
      }
    },
    {
      "@type": "Question",
      "name": "How long has ELM Construction been in business?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Elliott Pike founded ELM Construction in 2008, and the company grew through the worst economic downturn since the Great Depression on the strength of referrals and repeat clients. Elliott was named 2023 NAHB Remodeler of the Year and serves as 2026 Chair of the NAHB Remodelers. ELM has also earned multiple Alabama Remodeling Excellence Awards and Best of Houzz honors."
      }
    },
    {
      "@type": "Question",
      "name": "Can I see examples of your work and hear from past clients?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes! Our portfolio includes completed kitchens, bathrooms, basements, additions, and outdoor living projects across Vestavia Hills, Mountain Brook, Homewood, and Hoover, organized so you can browse by project type. Client reviews are published on both Google and Houzz, and we are glad to connect you with past clients who had projects similar to yours."
      }
    },
    {
      "@type": "Question",
      "name": "Do you offer a warranty on your work?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We back our work with a written two-year warranty (double the industry standard). Specific coverage is spelled out in your contract, so you know exactly what is included before construction begins rather than after."
      }
    },
    {
      "@type": "Question",
      "name": "How do I get started?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Book a consultation through our contact page, or call 205-273-2773. You do not need finished plans, a drawn-up design, or even a firm budget figure to start the conversation; you only need a sense of what is not working in your home."
      }
    }
  ]
}

